INSERT IGNORE INTO labs (id,title,slug,description,difficulty,category,points,lab_url,estimated_time,flag) VALUES
(1,'SQL Injection Awareness','tm-01-sql-injection-awareness','Learn how attackers manipulate SQL queries through unsanitized user input to extract, modify, or delete database data. Covers classic UNION-based and error-based techniques.','P1','Injection',100,'/labs/tm-01/login',30,'FLAG{tm-01-sql-injection}'),
(2,'Blind SQL Injection Awareness','tm-02-blind-sql-injection-awareness','Explore SQL injection scenarios where no direct output is returned. Understand boolean-based and time-based blind techniques to infer data from the database.','P2','Injection',100,'/labs/tm-02',45,'FLAG{tm-02-blind-sqli}'),
(3,'Second-Order SQL Injection Awareness','tm-03-second-order-sql-injection-awareness','Investigate how injected payloads stored safely at first can be executed later in a different context, bypassing input validation that only runs at insertion time.','P3','Injection',100,'/labs/tm-03',60,'FLAG{tm-03-second-order-sqli}'),
(4,'NoSQL Injection Awareness','tm-04-nosql-injection-awareness','Understand injection attacks targeting NoSQL databases like MongoDB. Learn how operator injection and query manipulation can bypass authentication and expose data.','P2','Injection',100,'/labs/tm-04',40,'FLAG{tm-04-nosql-injection}'),
(5,'Command Injection Awareness','tm-05-command-injection-awareness','Discover how unsanitized input passed to OS shell commands allows attackers to execute arbitrary commands on the server, leading to full system compromise.','P2','Injection',100,'/labs/tm-05',40,'FLAG{tm-05-cmd-injection}'),
(6,'Server-Side Template Injection Awareness','tm-06-ssti-awareness','Learn how user-controlled input rendered inside server-side templates can lead to remote code execution by abusing the template engine evaluation context.','P4','Injection',100,'/labs/tm-06',60,'FLAG{tm-06-ssti}'),
(7,'XML Processing Security Scenario','tm-16-xml-processing-security','Explore XXE (XML External Entity) vulnerabilities and how malicious XML input can be used to read local files, perform SSRF, or cause denial of service.','P3','Injection',100,'/labs/tm-16',50,'FLAG{tm-16-xxe}'),
(8,'Authentication Bypass Scenario','tm-07-authentication-bypass','Examine common authentication bypass techniques including logic flaws, parameter tampering, and missing validation checks that allow unauthorized access.','P2','Authentication & Session Management',100,'/labs/tm-07',40,'FLAG{tm-07-auth-bypass}'),
(9,'OAuth Account Takeover Scenario','tm-08-oauth-account-takeover','Understand how misconfigurations in OAuth 2.0 flows such as improper state validation or redirect URI manipulation can lead to full account takeover.','P4','Authentication & Session Management',100,'/labs/tm-08',60,'FLAG{tm-08-oauth-takeover}'),
(10,'JWT Security Scenario','tm-09-jwt-security','Learn about JWT vulnerabilities including the none algorithm attack, weak secret brute-forcing, and algorithm confusion attacks that allow token forgery.','P2','Authentication & Session Management',100,'/labs/tm-09',45,'FLAG{tm-09-jwt-security}'),
(11,'Session Management Scenario','tm-10-session-management','Explore insecure session handling issues such as predictable session tokens, session fixation, and improper invalidation after logout.','P2','Authentication & Session Management',100,'/labs/tm-10',40,'FLAG{tm-10-session-mgmt}'),
(12,'Password Reset Security Scenario','tm-28-password-reset-security','Analyze weaknesses in password reset flows including token leakage via Referer headers, guessable tokens, and host header injection in reset emails.','P2','Authentication & Session Management',75,'/labs/tm-28',35,'FLAG{tm-28-password-reset}'),
(13,'Token Lifecycle Security Scenario','tm-29-token-lifecycle-security','Understand risks arising from improper token expiry, missing revocation mechanisms, and reuse of refresh tokens across sessions.','P2','Authentication & Session Management',75,'/labs/tm-29',35,'FLAG{tm-29-token-lifecycle}'),
(14,'Brute Force Protection Scenario','tm-50-brute-force-protection','Learn how missing rate limiting and account lockout mechanisms expose authentication endpoints to credential stuffing and brute force attacks.','P1','Authentication & Session Management',50,'/labs/tm-50',25,'FLAG{tm-50-brute-force}'),
(15,'Password Policy Awareness','tm-56-password-policy-awareness','Understand the importance of enforcing strong password policies and how weak policies contribute to account compromise via dictionary attacks.','P1','Authentication & Session Management',25,'/labs/tm-56',15,'FLAG{tm-56-password-policy}'),
(16,'Vertical IDOR Scenario','tm-11-vertical-idor','Explore insecure direct object reference vulnerabilities where a lower-privileged user can access or modify resources belonging to higher-privileged users.','P2','Broken Access Control',100,'/labs/tm-11',40,'FLAG{tm-11-vertical-idor}'),
(17,'Privilege Escalation Scenario','tm-12-privilege-escalation','Learn how attackers leverage parameter manipulation, mass assignment, or role logic flaws to elevate their privileges within an application.','P3','Broken Access Control',100,'/labs/tm-12',55,'FLAG{tm-12-priv-esc}'),
(18,'Horizontal IDOR Scenario','tm-23-horizontal-idor','Understand how predictable resource identifiers allow a user to access another user data at the same privilege level without authorization checks.','P1','Broken Access Control',75,'/labs/tm-23',30,'FLAG{tm-23-horizontal-idor}'),
(19,'BOLA Awareness Module','tm-24-bola-awareness','Broken Object Level Authorization ÔÇö learn how APIs failing to validate object ownership on every request expose sensitive user data to unauthorized parties.','P2','Broken Access Control',75,'/labs/tm-24',35,'FLAG{tm-24-bola}'),
(20,'BFLA Awareness Module','tm-25-bfla-awareness','Broken Function Level Authorization ÔÇö explore how missing function-level access controls allow regular users to invoke admin-only API actions.','P3','Broken Access Control',75,'/labs/tm-25',45,'FLAG{tm-25-bfla}'),
(21,'Missing Authorization Scenario','tm-26-missing-authorization','Examine endpoints that perform sensitive actions without any authorization checks, allowing unauthenticated or unauthorized users to trigger them directly.','P1','Broken Access Control',75,'/labs/tm-26',30,'FLAG{tm-26-missing-authz}'),
(22,'Object Ownership Validation Scenario','tm-27-object-ownership-validation','Learn how applications must verify that the requesting user owns or has explicit permission to the resource, not just that the user is authenticated.','P2','Broken Access Control',75,'/labs/tm-27',35,'FLAG{tm-27-object-ownership}'),
(23,'Forced Browsing Awareness','tm-47-forced-browsing-awareness','Understand how attackers enumerate unlinked or hidden endpoints and files by guessing paths, bypassing access controls through direct URL access.','P1','Broken Access Control',50,'/labs/tm-47',25,'FLAG{tm-47-forced-browsing}'),
(24,'GraphQL Object Authorization Scenario','tm-52-graphql-object-authorization','Explore how GraphQL resolvers that skip per-object authorization checks expose data from other users through query manipulation.','P3','Broken Access Control',50,'/labs/tm-52',45,'FLAG{tm-52-graphql-authz}'),
(25,'File Upload Security Scenario','tm-13-file-upload-security','Learn how improper file upload validation allows attackers to upload webshells or malicious files by bypassing extension, MIME type, and content checks.','P3','File Handling Vulnerabilities',100,'/labs/tm-13',55,'FLAG{tm-13-file-upload}'),
(26,'Arbitrary File Access Awareness','tm-30-arbitrary-file-access','Understand how unsanitized file path parameters can be abused to read arbitrary files from the server filesystem, including sensitive configuration files.','P2','File Handling Vulnerabilities',75,'/labs/tm-30',35,'FLAG{tm-30-arbitrary-file}'),
(27,'Path Traversal Awareness','tm-31-path-traversal-awareness','Explore directory traversal attacks using ../ sequences to escape the intended file root and access files outside the application designated directory.','P2','File Handling Vulnerabilities',75,'/labs/tm-31',35,'FLAG{tm-31-path-traversal}'),
(28,'File Inclusion Awareness','tm-32-file-inclusion-awareness','Learn about Local File Inclusion and Remote File Inclusion vulnerabilities that allow attackers to include and execute unintended files on the server.','P3','File Handling Vulnerabilities',75,'/labs/tm-32',50,'FLAG{tm-32-file-inclusion}'),
(29,'SSRF Concept Demonstration','tm-14-ssrf-concept','Understand Server-Side Request Forgery ÔÇö how attackers trick the server into making requests to internal services, cloud metadata endpoints, or arbitrary URLs.','P3','Server-Side Vulnerabilities',100,'/labs/tm-14',55,'FLAG{tm-14-ssrf}'),
(30,'Internal Resource Access Scenario','tm-15-internal-resource-access','Explore SSRF exploitation targeting internal network resources such as admin panels, databases, and cloud provider metadata APIs not exposed to the internet.','P3','Server-Side Vulnerabilities',100,'/labs/tm-15',55,'FLAG{tm-15-internal-ssrf}'),
(31,'HTTP Request Smuggling Awareness','tm-18-http-request-smuggling','Learn how discrepancies in how front-end and back-end servers parse HTTP request boundaries enable request smuggling attacks to poison request queues.','P4','Server-Side Vulnerabilities',100,'/labs/tm-18',65,'FLAG{tm-18-http-smuggling}'),
(32,'Insecure Deserialization Awareness','tm-19-insecure-deserialization','Explore how deserializing untrusted data without validation can lead to remote code execution, privilege escalation, or denial of service attacks.','P4','Server-Side Vulnerabilities',100,'/labs/tm-19',65,'FLAG{tm-19-deserial}'),
(33,'Cache Poisoning Awareness','tm-40-cache-poisoning-awareness','Understand how unkeyed HTTP headers or parameters can be used to poison cached responses, delivering malicious content to other users from the cache.','P3','Server-Side Vulnerabilities',75,'/labs/tm-40',50,'FLAG{tm-40-cache-poison}'),
(34,'Host Header Security Scenario','tm-53-host-header-security','Learn how trusting the Host header without validation enables attacks like password reset poisoning, cache poisoning, and SSRF via host header injection.','P2','Server-Side Vulnerabilities',50,'/labs/tm-53',35,'FLAG{tm-53-host-header}'),
(35,'CORS Security Scenario','tm-54-cors-security','Explore misconfigured Cross-Origin Resource Sharing policies that allow malicious origins to make credentialed cross-origin requests and steal sensitive data.','P2','Server-Side Vulnerabilities',50,'/labs/tm-54',35,'FLAG{tm-54-cors}'),
(36,'Error Handling & Information Disclosure Scenario','tm-58-error-handling-info-disclosure','Understand how verbose error messages and stack traces leak internal implementation details, paths, and credentials useful to attackers during reconnaissance.','P1','Server-Side Vulnerabilities',25,'/labs/tm-58',15,'FLAG{tm-58-error-disclosure}'),
(37,'Stored XSS Awareness','tm-21-stored-xss-awareness','Learn how malicious scripts persisted in the database are served to other users, enabling session hijacking, phishing, and keylogging attacks at scale.','P2','Client-Side Vulnerabilities',75,'/labs/tm-21',40,'FLAG{tm-21-stored-xss}'),
(38,'Blind XSS Awareness','tm-22-blind-xss-awareness','Explore XSS payloads that execute in contexts not directly visible to the attacker, such as admin panels, triggering out-of-band callbacks to attacker infrastructure.','P3','Client-Side Vulnerabilities',75,'/labs/tm-22',50,'FLAG{tm-22-blind-xss}'),
(39,'Reflected XSS Awareness','tm-41-reflected-xss-awareness','Understand reflected XSS where user-supplied input is immediately returned in the response unsanitized, requiring social engineering to deliver the attack.','P1','Client-Side Vulnerabilities',50,'/labs/tm-41',25,'FLAG{tm-41-reflected-xss}'),
(40,'DOM XSS Awareness','tm-42-dom-xss-awareness','Explore DOM-based XSS where JavaScript reads from attacker-controlled sources like location.hash and writes to dangerous sinks without server involvement.','P3','Client-Side Vulnerabilities',50,'/labs/tm-42',45,'FLAG{tm-42-dom-xss}'),
(41,'Markdown Rendering Security Scenario','tm-43-markdown-rendering-security','Learn how unsafe Markdown renderers that allow raw HTML or javascript URIs can be abused to inject scripts or phishing links into rendered content.','P2','Client-Side Vulnerabilities',50,'/labs/tm-43',35,'FLAG{tm-43-markdown-xss}'),
(42,'SVG Handling Security Scenario','tm-44-svg-handling-security','Understand how SVG files containing embedded scripts or foreign objects can execute JavaScript when rendered inline in the browser, bypassing upload filters.','P2','Client-Side Vulnerabilities',50,'/labs/tm-44',35,'FLAG{tm-44-svg-xss}'),
(43,'Rich Text Editor Security Scenario','tm-45-rich-text-editor-security','Explore how inadequate sanitization of rich text editor output allows injection of malicious HTML and scripts that survive rendering in other users browsers.','P3','Client-Side Vulnerabilities',50,'/labs/tm-45',45,'FLAG{tm-45-rte-xss}'),
(44,'CSRF Awareness','tm-46-csrf-awareness','Learn how Cross-Site Request Forgery exploits authenticated sessions by tricking users into unknowingly submitting state-changing requests from attacker-controlled pages.','P2','Client-Side Vulnerabilities',50,'/labs/tm-46',35,'FLAG{tm-46-csrf}'),
(45,'Clickjacking Awareness','tm-55-clickjacking-awareness','Understand how attackers overlay transparent iframes over legitimate UI elements to trick users into clicking hidden buttons and performing unintended actions.','P1','Client-Side Vulnerabilities',25,'/labs/tm-55',15,'FLAG{tm-55-clickjacking}'),
(46,'Redirect Validation Scenario','tm-57-redirect-validation','Learn how unvalidated redirect parameters can be abused for phishing by redirecting users to attacker-controlled sites after authentication or actions.','P1','Client-Side Vulnerabilities',25,'/labs/tm-57',15,'FLAG{tm-57-open-redirect}'),
(47,'Webhook Security Scenario','tm-33-webhook-security','Explore webhook vulnerabilities including missing signature validation, SSRF via callback URLs, and replay attacks that allow tampering with event-driven flows.','P2','API Security',75,'/labs/tm-33',40,'FLAG{tm-33-webhook}'),
(48,'GraphQL Mutation Security Scenario','tm-34-graphql-mutation-security','Learn how GraphQL mutations lacking proper authorization and input validation can be exploited to modify other users data or perform privileged operations.','P3','API Security',75,'/labs/tm-34',50,'FLAG{tm-34-graphql-mutation}'),
(49,'API Key Management Scenario','tm-35-api-key-management','Understand risks of hardcoded API keys, overly permissive key scopes, missing key rotation, and key leakage through client-side code or public repositories.','P1','API Security',75,'/labs/tm-35',30,'FLAG{tm-35-api-key}'),
(50,'Mass Assignment Awareness','tm-39-mass-assignment-awareness','Explore how APIs that automatically bind request body fields to object properties can be exploited to set unauthorized fields like isAdmin or accountBalance.','P2','API Security',75,'/labs/tm-39',35,'FLAG{tm-39-mass-assignment}'),
(51,'Excessive Data Exposure Awareness','tm-48-excessive-data-exposure','Learn how APIs returning full data objects and relying on clients to filter sensitive fields expose private data to anyone intercepting or inspecting API responses.','P1','API Security',50,'/labs/tm-48',25,'FLAG{tm-48-data-exposure}'),
(52,'Rate Limiting Awareness','tm-49-rate-limiting-awareness','Understand the impact of missing rate limits on API endpoints enabling brute force, scraping, SMS pumping, and resource exhaustion attacks at scale.','P1','API Security',50,'/labs/tm-49',20,'FLAG{tm-49-rate-limit}'),
(53,'API Parameter Pollution Awareness','tm-51-api-parameter-pollution','Explore HTTP Parameter Pollution techniques where duplicate parameters are injected to confuse server-side parsing logic and bypass security controls.','P2','API Security',50,'/labs/tm-51',35,'FLAG{tm-51-param-pollution}'),
(54,'GraphQL Introspection Awareness','tm-59-graphql-introspection-awareness','Learn how enabled GraphQL introspection in production exposes the full schema to attackers, aiding reconnaissance for injection and authorization attacks.','P1','API Security',25,'/labs/tm-59',15,'FLAG{tm-59-graphql-introspection}'),
(55,'Payment Validation Logic Scenario','tm-17-payment-validation-logic','Explore business logic flaws in payment workflows such as negative price manipulation, currency confusion, and skipping payment steps through request tampering.','P3','Business Logic',100,'/labs/tm-17',60,'FLAG{tm-17-payment-logic}'),
(56,'Race Condition Awareness','tm-36-race-condition-awareness','Understand how concurrent requests exploiting time-of-check to time-of-use flaws enable double spending, duplicate coupon redemption, and limit bypasses.','P4','Business Logic',75,'/labs/tm-36',60,'FLAG{tm-36-race-condition}'),
(57,'Price Manipulation Logic Scenario','tm-37-price-manipulation-logic','Learn how client-side or hidden parameter trust in pricing logic allows attackers to purchase items at manipulated prices or for free.','P2','Business Logic',75,'/labs/tm-37',40,'FLAG{tm-37-price-manipulation}'),
(58,'Coupon Validation Scenario','tm-38-coupon-validation','Explore flaws in coupon and discount validation logic that allow stacking unlimited discounts, reusing single-use codes, or applying codes beyond their intended scope.','P2','Business Logic',75,'/labs/tm-38',40,'FLAG{tm-38-coupon-bypass}'),
(59,'Dependency Management Security Scenario','tm-20-dependency-management-security','Learn about risks from outdated dependencies, typosquatting, dependency confusion attacks, and how malicious packages in the supply chain compromise applications.','P2','Software Supply Chain',100,'/labs/tm-20',50,'FLAG{tm-20-supply-chain}'),
(60,'Subdomain Takeover Awareness','tm-60-subdomain-takeover-awareness','Understand how dangling DNS records pointing to deprovisioned cloud services allow attackers to claim the subdomain and serve malicious content under the target domain.','P3','Reconnaissance & Asset Discovery',25,'/labs/tm-60',20,'FLAG{tm-60-subdomain-takeover}');
INSERT IGNORE INTO lab_meta (lab_id,objectives,scenario,hints,resources) VALUES
(1,'[\"Identify common injection entry points in web applications\",\"Craft and test injection payloads relevant to SQL Injection Awareness\",\"Retrieve or manipulate data through successful exploitation\",\"Understand mitigation techniques and secure coding practices\"]','[\"You have been brought in as a security consultant for a mid-sized e-commerce platform.\",\"The development team uses a backend that is vulnerable to SQL Injection Awareness.\",\"During initial recon you notice that several input fields are passed directly to the backend without sanitization.\",\"Your objective is to exploit the vulnerability, extract the hidden flag, and document the impact.\"]','[\"Try injecting special characters into every input field.\",\"Think about how the server constructs its query — what happens with a single quote or operator?\",\"Burp Suite or a browser proxy will help you intercept and modify requests.\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/www-community/Injection_Flaws\",\"title\":\"OWASP – Injection\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/SQL_Injection_Prevention_Cheat_Sheet.html\",\"title\":\"OWASP SQL Injection Prevention Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/sql-injection\",\"title\":\"PortSwigger – Injection\"}]'),
