(16,'[\"Identify missing or misconfigured authorization checks in Vertical IDOR Scenario\",\"Exploit object-level and function-level access flaws\",\"Access resources belonging to other users or roles\",\"Apply correct authorization patterns to prevent the flaw\"]','[\"A healthcare portal stores patient records accessible only to authorized staff.\",\"A recent code audit flagged missing authorization checks related to Vertical IDOR Scenario.\",\"You have been granted a low-privilege account to simulate what a malicious user could access.\",\"Your objective is to escalate access and retrieve data that should be off-limits to your role.\"]','[\"Try accessing other users\' resources by changing an ID in the request.\",\"Are there admin-only endpoints hinted at in the JavaScript or API docs?\",\"Check if authorization is enforced on every HTTP method (GET, POST, PUT, DELETE).\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/Top10/A01_2021-Broken_Access_Control/\",\"title\":\"OWASP Broken Access Control\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/Insecure_Direct_Object_Reference_Prevention_Cheat_Sheet.html\",\"title\":\"OWASP IDOR Prevention Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/access-control\",\"title\":\"PortSwigger – Access Control\"}]'),
