(25,'[\"Identify unsafe file handling logic relevant to File Upload Security Scenario\",\"Exploit path traversal or unrestricted upload issues\",\"Access or execute unintended server-side files\",\"Apply secure file validation and storage practices\"]','[\"A document management system allows authenticated users to upload and retrieve files.\",\"The engineering team used a custom implementation for file handling, leaving it vulnerable to File Upload Security Scenario.\",\"An internal audit suspects users may reach files outside the intended storage directory.\",\"Your task is to exploit the file handling flaw and locate the hidden flag on the server.\"]','[\"Try using ../ sequences in file path parameters.\",\"Does the upload endpoint validate MIME type client-side or server-side?\",\"Check the HTTP response for hints about the server file system layout.\"]','[{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/File_Upload_Cheat_Sheet.html\",\"title\":\"OWASP File Upload Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-upload\",\"title\":\"PortSwigger – File Upload Vulnerabilities\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-path-traversal\",\"title\":\"PortSwigger – Path Traversal\"}]'),
(26,'[\"Identify unsafe file handling logic relevant to Arbitrary File Access Awareness\",\"Exploit path traversal or unrestricted upload issues\",\"Access or execute unintended server-side files\",\"Apply secure file validation and storage practices\"]','[\"A document management system allows authenticated users to upload and retrieve files.\",\"The engineering team used a custom implementation for file handling, leaving it vulnerable to Arbitrary File Access Awareness.\",\"An internal audit suspects users may reach files outside the intended storage directory.\",\"Your task is to exploit the file handling flaw and locate the hidden flag on the server.\"]','[\"Try using ../ sequences in file path parameters.\",\"Does the upload endpoint validate MIME type client-side or server-side?\",\"Check the HTTP response for hints about the server file system layout.\"]','[{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/File_Upload_Cheat_Sheet.html\",\"title\":\"OWASP File Upload Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-upload\",\"title\":\"PortSwigger – File Upload Vulnerabilities\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-path-traversal\",\"title\":\"PortSwigger – Path Traversal\"}]'),
(27,'[\"Identify unsafe file handling logic relevant to Path Traversal Awareness\",\"Exploit path traversal or unrestricted upload issues\",\"Access or execute unintended server-side files\",\"Apply secure file validation and storage practices\"]','[\"A document management system allows authenticated users to upload and retrieve files.\",\"The engineering team used a custom implementation for file handling, leaving it vulnerable to Path Traversal Awareness.\",\"An internal audit suspects users may reach files outside the intended storage directory.\",\"Your task is to exploit the file handling flaw and locate the hidden flag on the server.\"]','[\"Try using ../ sequences in file path parameters.\",\"Does the upload endpoint validate MIME type client-side or server-side?\",\"Check the HTTP response for hints about the server file system layout.\"]','[{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/File_Upload_Cheat_Sheet.html\",\"title\":\"OWASP File Upload Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-upload\",\"title\":\"PortSwigger – File Upload Vulnerabilities\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-path-traversal\",\"title\":\"PortSwigger – Path Traversal\"}]'),
(28,'[\"Identify unsafe file handling logic relevant to File Inclusion Awareness\",\"Exploit path traversal or unrestricted upload issues\",\"Access or execute unintended server-side files\",\"Apply secure file validation and storage practices\"]','[\"A document management system allows authenticated users to upload and retrieve files.\",\"The engineering team used a custom implementation for file handling, leaving it vulnerable to File Inclusion Awareness.\",\"An internal audit suspects users may reach files outside the intended storage directory.\",\"Your task is to exploit the file handling flaw and locate the hidden flag on the server.\"]','[\"Try using ../ sequences in file path parameters.\",\"Does the upload endpoint validate MIME type client-side or server-side?\",\"Check the HTTP response for hints about the server file system layout.\"]','[{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/File_Upload_Cheat_Sheet.html\",\"title\":\"OWASP File Upload Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-upload\",\"title\":\"PortSwigger – File Upload Vulnerabilities\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/file-path-traversal\",\"title\":\"PortSwigger – Path Traversal\"}]'),
(29,'[\"Understand server-side request parsing and execution in the context of SSRF Concept Demonstration\",\"Craft payloads targeting internal server behavior\",\"Trigger unintended actions via vulnerable server logic\",\"Understand mitigations and secure design patterns\"]','[\"A financial services platform exposes an internal feature to authenticated users.\",\"The feature is vulnerable to SSRF Concept Demonstration via user-supplied parameters.\",\"Internal network segments — including a metadata service — are reachable from the application server.\",\"Your objective is to pivot through the server-side request to reach restricted resources and find the flag.\"]','[\"Try pointing URL parameters to http://127.0.0.1 or http://169.254.169.254.\",\"What internal services might be reachable from the server?\",\"Try different URL schemes: file://, dict://, gopher://.\"]','[{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/ssrf\",\"title\":\"PortSwigger – SSRF\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/Server_Side_Request_Forgery_Prevention_Cheat_Sheet.html\",\"title\":\"OWASP SSRF Prevention Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/request-smuggling\",\"title\":\"PortSwigger – HTTP Request Smuggling\"}]'),
