(47,'[\"Identify insecure API design patterns related to Webhook Security Scenario\",\"Exploit authorization, exposure, or parameter issues\",\"Retrieve sensitive data or perform unauthorized actions\",\"Apply API security best practices and rate limiting\"]','[\"A logistics company recently launched a REST API to integrate with third-party partners.\",\"The API was built quickly with a focus on features, leaving it vulnerable to Webhook Security Scenario.\",\"You have obtained a valid low-privilege API token through their public developer portal.\",\"Your mission is to exploit the API security flaw and access data beyond your authorization scope.\"]','[\"Intercept API calls and look for IDs or object references you can manipulate.\",\"Are there fields in the response you can try sending back in a write request?\",\"Check if the API uses numeric sequential IDs — can you enumerate them?\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/www-project-api-security/\",\"title\":\"OWASP API Security Top 10\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html\",\"title\":\"OWASP REST Security Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/api-testing\",\"title\":\"PortSwigger – API Testing\"}]'),
(48,'[\"Identify insecure API design patterns related to GraphQL Mutation Security Scenario\",\"Exploit authorization, exposure, or parameter issues\",\"Retrieve sensitive data or perform unauthorized actions\",\"Apply API security best practices and rate limiting\"]','[\"A logistics company recently launched a REST API to integrate with third-party partners.\",\"The API was built quickly with a focus on features, leaving it vulnerable to GraphQL Mutation Security Scenario.\",\"You have obtained a valid low-privilege API token through their public developer portal.\",\"Your mission is to exploit the API security flaw and access data beyond your authorization scope.\"]','[\"Intercept API calls and look for IDs or object references you can manipulate.\",\"Are there fields in the response you can try sending back in a write request?\",\"Check if the API uses numeric sequential IDs — can you enumerate them?\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/www-project-api-security/\",\"title\":\"OWASP API Security Top 10\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html\",\"title\":\"OWASP REST Security Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/api-testing\",\"title\":\"PortSwigger – API Testing\"}]'),
(49,'[\"Identify insecure API design patterns related to API Key Management Scenario\",\"Exploit authorization, exposure, or parameter issues\",\"Retrieve sensitive data or perform unauthorized actions\",\"Apply API security best practices and rate limiting\"]','[\"A logistics company recently launched a REST API to integrate with third-party partners.\",\"The API was built quickly with a focus on features, leaving it vulnerable to API Key Management Scenario.\",\"You have obtained a valid low-privilege API token through their public developer portal.\",\"Your mission is to exploit the API security flaw and access data beyond your authorization scope.\"]','[\"Intercept API calls and look for IDs or object references you can manipulate.\",\"Are there fields in the response you can try sending back in a write request?\",\"Check if the API uses numeric sequential IDs — can you enumerate them?\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/www-project-api-security/\",\"title\":\"OWASP API Security Top 10\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html\",\"title\":\"OWASP REST Security Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/api-testing\",\"title\":\"PortSwigger – API Testing\"}]'),
(50,'[\"Identify insecure API design patterns related to Mass Assignment Awareness\",\"Exploit authorization, exposure, or parameter issues\",\"Retrieve sensitive data or perform unauthorized actions\",\"Apply API security best practices and rate limiting\"]','[\"A logistics company recently launched a REST API to integrate with third-party partners.\",\"The API was built quickly with a focus on features, leaving it vulnerable to Mass Assignment Awareness.\",\"You have obtained a valid low-privilege API token through their public developer portal.\",\"Your mission is to exploit the API security flaw and access data beyond your authorization scope.\"]','[\"Intercept API calls and look for IDs or object references you can manipulate.\",\"Are there fields in the response you can try sending back in a write request?\",\"Check if the API uses numeric sequential IDs — can you enumerate them?\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/www-project-api-security/\",\"title\":\"OWASP API Security Top 10\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html\",\"title\":\"OWASP REST Security Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/api-testing\",\"title\":\"PortSwigger – API Testing\"}]'),
(51,'[\"Identify insecure API design patterns related to Excessive Data Exposure Awareness\",\"Exploit authorization, exposure, or parameter issues\",\"Retrieve sensitive data or perform unauthorized actions\",\"Apply API security best practices and rate limiting\"]','[\"A logistics company recently launched a REST API to integrate with third-party partners.\",\"The API was built quickly with a focus on features, leaving it vulnerable to Excessive Data Exposure Awareness.\",\"You have obtained a valid low-privilege API token through their public developer portal.\",\"Your mission is to exploit the API security flaw and access data beyond your authorization scope.\"]','[\"Intercept API calls and look for IDs or object references you can manipulate.\",\"Are there fields in the response you can try sending back in a write request?\",\"Check if the API uses numeric sequential IDs — can you enumerate them?\"]','[{\"sub\":\"owasp.org\",\"href\":\"https://owasp.org/www-project-api-security/\",\"title\":\"OWASP API Security Top 10\"},{\"sub\":\"cheatsheetseries.owasp.org\",\"href\":\"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html\",\"title\":\"OWASP REST Security Cheat Sheet\"},{\"sub\":\"portswigger.net\",\"href\":\"https://portswigger.net/web-security/api-testing\",\"title\":\"PortSwigger – API Testing\"}]'),
